    public bool rsready
    {
      get
      {
        if (!this.HasSkill("Rear Strike", true) || !this.CanSkill("Rear Strike", true))
          return false;
        return this.IgnoreHP(this.MainTarget.Image) || this.MainTarget.HpAmount > 20.0;
      }
    }

    public bool asready
    {
      get
      {
        if (!this.HasSkill("Assassin Strike") || !this.CanSkill("Assassin Strike") || !this.MainTarget.IsInFront(this.ServerLocation))
          return false;
        return this.IgnoreHP(this.MainTarget.Image) || this.MainTarget.HpAmount > 20.0;
      }
    }


