    public bool hasdf => this.Characters.ContainsKey(this.PlayerID) && this.Characters[this.PlayerID] != null && Server.StaticCharacters.ContainsKey(this.PlayerID) && Server.StaticCharacters[this.PlayerID] != null && Server.StaticCharacters[this.PlayerID].SpellAnimationHistory.ContainsKey(271) && DateTime.UtcNow.Subtract(Server.StaticCharacters[this.PlayerID].SpellAnimationHistory[271]).TotalSeconds < 19.0;

    public bool hasasgall => this.Characters.ContainsKey(this.PlayerID) && this.Characters[this.PlayerID] != null && Server.StaticCharacters.ContainsKey(this.PlayerID) && Server.StaticCharacters[this.PlayerID] != null && Server.StaticCharacters[this.PlayerID].SpellAnimationHistory.ContainsKey(66) && DateTime.UtcNow.Subtract(Server.StaticCharacters[this.PlayerID].SpellAnimationHistory[66]).TotalSeconds < 12.0;

    public bool hashide => !(this.hidetime == DateTime.MinValue) && DateTime.UtcNow.Subtract(this.hidetime).TotalSeconds < 45.0;

    public bool canpf
    {
      get
      {
        if (this.HasSkill("Animal Roar") && !this.CanSkill("Animal Roar") || this.HasSkill("Ground Stomp") && !this.CanSkill("Ground Stomp") || this.HasSkill("Paralyze Force") && !this.CanSkill("Paralyze Force"))
          return false;
        return this.pftime == DateTime.MinValue || DateTime.UtcNow.Subtract(this.pftime).TotalSeconds > 26.0;
      }
    }

    public bool amIActive() => this.mainProc != null && User32.GetForegroundWindow() == this.mainProc.MainWindowHandle;

    public int DistanceFrom(Location loc) => Math.Abs(this.ServerLocation.X - loc.X) + Math.Abs(this.ServerLocation.Y - loc.Y);

    private int RandomNumber(int min, int max) => this.random.Next(min, max);

