    private void EntityNameLoop()
    {
      EntityNameThreadRunning = true;
      while (EntityNameThreadRunning)
      {
        try
        {
          if (this.Tab.studycreaturetxt.Checked 
              && (this.sensedelay == DateTime.MinValue || DateTime.UtcNow.Subtract(this.sensedelay).TotalMilliseconds > 800.0) 
              && (this.CanSkill("Study Creature") || this.CanSkill("Echo Sense") || this.CanSkill("Martial Awareness") || this.CanSkill("Combat Senses")))
          {
            foreach (Npc allNearbyMonster in this.AllNearbyMonsters())
            {
              if (allNearbyMonster != null && !allNearbyMonster.sensed && allNearbyMonster.IsInRSRange(this.ServerLocation, 3))
              {
                if (this.CanSkill("Study Creature"))
                {
                  this.blocklores = true;
                  this.UseSkill("Study Creature");
                  this.sensedelay = DateTime.UtcNow;
                  break;
                }
                if (this.CanSkill("Echo Sense"))
                {
                  this.blocklores = true;
                  this.UseSkill("Echo Sense");
                  this.sensedelay = DateTime.UtcNow;
                  break;
                }
                if (this.CanSkill("Martial Awareness"))
                {
                  this.blocklores = true;
                  this.UseSkill("Martial Awareness");
                  this.sensedelay = DateTime.UtcNow;
                  break;
                }
                if (this.CanSkill("Combat Senses"))
                {
                  this.blocklores = true;
                  this.UseSkill("Combat Senses");
                  this.sensedelay = DateTime.UtcNow;
                  break;
                }
                break;
              }
            }
          }
        }
        catch
        {
        }
        Thread.Sleep(200);
      }
    }

    private DugonColor? GetDugonColor()
    {
      if (Enum.TryParse(attemptingdugon, true, out DugonColor color))
        return color;

      return null;
    }

    private void Questing()
    {
      QuestThreadRunning = true;
      while (QuestThreadRunning)
      {
        try
        {
