    public void SpellMonsters()
    {
      if (this.Statistics.CurrentHP == 0U || this.IsSkulled)
        return;
      Npc[] npcArray1 = this.NearestMonsters();
      if (this.Tab.allMonsters != null && this.MapInfo != null && this.MapInfo.IsLoaded)
      {
        if (this.Tab.openmedchest.Checked)
        {
          npcArray1 = this.Asilon();
        }
        else
        {
          npcArray1 = !this.Tab.allMonsters.targettype.Text.Equals("Highest Hp") ? (!this.Tab.allMonsters.targettype.Text.Equals("Lowest Hp") ? (!this.Tab.allMonsters.targettype.Text.Equals("Farthest") ? this.NearestMonsters() : this.farthestMonsters()) : this.LowestHPMonster()) : this.HighestHPMonster();
          if (this.MapInfo.Name.Contains("Chaos"))
            npcArray1 = this.ChaosAI(npcArray1);
          else if (this.MapInfo.Name.Contains("Mount Giragan") || this.MapInfo.Name.Contains("Ice Cave"))
            npcArray1 = this.MTGAI(npcArray1);
          else if (this.MapInfo.Name.Contains("Cthonic Remains"))
            npcArray1 = this.CRAI(npcArray1);
