      ServerPacket msg = new ServerPacket((byte) 26);
      msg.WriteUInt32(id);
      msg.WriteByte((byte) 1);
      msg.WriteByte((byte) 0);
      msg.WriteUInt16((ushort) (5120 + effect));
      msg.WriteByte((byte) 0);
      msg.Write(new byte[3]);
      this.Enqueue(msg);
    }

