        if (obj != null && item.InventorySlot == obj.InventorySlot && obj.IsIdentified)
          return false;
      }
      return Server.NeedsIdentifiedList.Contains(item.Name) || Server.IdentifyItems.Contains(item.Name.ToLower());
    }

    public void AutoDeposit(string name)
    {
      if (this.swappingitem || this.ItemSlot(this.firstitemslot) != 1)
        return;
      if (this.MapInfo.Name.Contains("Storage") || this.MapInfo.Name.Contains("Rucesion Empty Room 1") || this.MapInfo.Name.Contains("Bank") || this.MapInfo.Name.Equals("Bank of Plamit") || this.MapInfo.Name.Equals("Pravat South Entrance") || this.MapInfo.Name.Equals("Grand Coliseum") || this.MapInfo.Name.Equals("Gladiator Arena Entrance"))
      {
        foreach (Item obj in this.Inventory)
        {
          if (obj != null && obj.Name.Equals(name, StringComparison.CurrentCultureIgnoreCase))
            this.Deposit(name, (int) this.ItemCount(name));
        }
      }
      else
      {
        if (!this.Tab.haxdeposit.Checked || !this.SafeToWalkFast)
          return;
        uint num = 0;
        Npc[] source = this.NearbyNpcs(Npc.NpcType.Mundane);
        if (((IEnumerable<Npc>) source).Count<Npc>() > 0)
        {
          foreach (Npc npc in source)
          {
            if (npc != null && npc.IsOnScreen)
            {
              num = npc.ID;
              break;
            }
          }
        }
        if (num <= 0U)
          return;
        foreach (Item obj in this.Inventory)
        {
          if (obj != null && obj.Name.Equals(name, StringComparison.CurrentCultureIgnoreCase))
          {
            if (!this.SafeToWalkFast)
              break;
            if (obj.Amount > 1U)
            {
              this.DialogueRespond(new uint?(num), "Deposit " + obj.InventorySlot.ToString() + " [" + obj.Amount.ToString() + "]");
              this.PopupClose(new uint?(num));
              Thread.Sleep(1100);
            }
            else
            {
              this.DialogueRespond(new uint?(num), "Deposit " + obj.InventorySlot.ToString());
              this.PopupClose(new uint?(num));
              Thread.Sleep(1100);
            }
          }
        }
      }
    }

