    public void AutoWalker(int x, int y)
    {
      if (this.MapInfo == null || !this.MapInfo.IsLoaded)
        return;
      this.MapInfo.UpdateBlocks(this);
      Point[] walkPath = this.MapInfo.FindPath(this.ClientLocation.X, this.ClientLocation.Y, x, y, false);

      //
