      if (leader != null)
      {
        foreach (Npc npc2 in (IEnumerable<Npc>) ((IEnumerable<Npc>) source).OrderBy<Npc, int>((Func<Npc, int>) (e => e.Location.DistanceFrom(leader.Location))))
        {
          if (npc2 != null && !this.IgnoreAtLocation(npc2.Location) && npc2.IsOnScreen && npc2.IsInMaxView(this.ServerLocation, 12) && npc2.Image != 49 && npc2.Image != 87 && (((IEnumerable<Npc>) source).Count<Npc>() == 1 || !Server.StaticCharacters[npc2.ID].hasdion && !Server.StaticCharacters[npc2.ID].hasmonsterdion))
          {
            if (this.Tab.vfollowplayer && this.Tab.vfollowtarget != string.Empty)
            {
              leader = this.FindCharacterByName<Player>(this.Tab.vfollowtarget);
              if (leader != null && npc2.IsInMaxView(leader.Location, 7))
              {
                npc1 = npc2;
                break;
              }
            }
            else
            {
              npc1 = npc2;
              break;
            }
          }
        }
      }
      return npc1;
    }

