            this.UseMedSkill(str);
          else if (str.Equals("pounce", StringComparison.CurrentCultureIgnoreCase) && this.HasSkill(str, true))
            this.UseMedSkill(str);
          else if (str.Equals("tail sweep", StringComparison.CurrentCultureIgnoreCase) && this.HasSkill(str, true))
            this.UseMedSkill(str);
          else if (str.Equals("claw slash", StringComparison.CurrentCultureIgnoreCase) && this.HasSkill(str, true))
            this.UseMedSkill(str);
          else if (str.Equals("venom attack", StringComparison.CurrentCultureIgnoreCase) && this.HasSkill(str, true))
            this.UseMedSkill(str);
          else if (str.Equals("kidney shot", StringComparison.CurrentCultureIgnoreCase) && this.HasSkill(str, true))
            this.UseMedSkill(str);
          else if (this.HasSkill(str))
            this.UseSkill(str);
          else if (str.Equals("~"))
          {
            this.UnequipSlot((byte) 1);
            this.UnequipSlot((byte) 3);
            Thread.Sleep(100);
          }
          else if (str.Equals("F5") || str.Equals("f5"))
            this.Refresh();
          else if (str.Equals("space", StringComparison.CurrentCultureIgnoreCase))
            this.Assail();
          else if (str.Equals("combo", StringComparison.CurrentCultureIgnoreCase))
          {
            this.UseItem("Two Move Combo");
            this.UseItem("Three Move Combo");
          }
          else if (str.Equals("stone skin", StringComparison.CurrentCultureIgnoreCase) && this.HasSpell("Stone Skin"))
          {
            while (!this.SpellBar.Contains((ushort) 53))
            {
              this.MacroCast("Stone Skin", new uint?());
              Thread.Sleep(100);
            }
          }
          else if (str.Equals("dion", StringComparison.CurrentCultureIgnoreCase) && this.HasSpell("dion"))
          {
            do
            {
              this.MacroCast("dion", new uint?());
              Thread.Sleep(100);
            }
            while (!this.SpellBar.Contains((ushort) 53));
          }
          else if (str.Equals("draco stance", StringComparison.CurrentCultureIgnoreCase) && this.HasSpell("draco stance"))
          {
            do
            {
              this.MacroCast("draco stance", new uint?());
              Thread.Sleep(100);
            }
            while (!this.SpellBar.Contains((ushort) 53));
          }
          else if (str.Equals("hide", StringComparison.CurrentCultureIgnoreCase))
          {
            if (this.HasSpell("Hide"))
              this.CastSpell("Hide");
            if (this.HasSpell("White Bat Stance"))
              this.CastSpell("White Bat Stance");
          }
          else if (str.Equals("form", StringComparison.CurrentCultureIgnoreCase))
          {
            foreach (Spell spell in this.SpellBook)
            {
              if (spell != null && spell.Name.Contains(" Form"))
              {
                this.MacroCast(spell.Name, new uint?());
                break;
              }
            }
          }
          else if (str.Equals("great poison snare", StringComparison.CurrentCultureIgnoreCase))
          {
            if (this.HasSpell("Great Poison Snare"))
              this.CastSpell("Great Poison Snare");
          }
          else if (str.Equals("cold blood", StringComparison.CurrentCultureIgnoreCase))
          {
            if (this.HasSpell("Cold Blood"))
              this.CastSpell("Cold Blood");
          }
          else if (str.Equals("gentle touch", StringComparison.CurrentCultureIgnoreCase))
          {
            if (this.HasSpell("Gentle Touch"))
              this.CastSpell("Gentle Touch");
          }
          else if (this.HasSpell(str))
            this.CastSpell(str, new uint?(this.PlayerID));
          else if (str.StartsWith("d:", StringComparison.CurrentCultureIgnoreCase))
            Thread.Sleep(int.Parse(str.Split(':')[1]));
          else if (this.HasItem(str))
            this.UseItem(str);
        }
      }
    })).Start();


    public void FindAutoWalkPath(int destinationMap)
    {
      // Handle current map case
      if (MapInfo.Number == destinationMap &&
          Tab.autowalker_button.Text == "Stop" &&
          !HasAWPath)
      {
        if (TryUseDefaultPath(destinationMap))
          return;

        ResetAutoWalk();
        return;
      }

      if (MapInfo.Number == destinationMap || HasAWPath)
        return;

      ResetCheckedFlags();

      var path = FindShortestPath(MapInfo.Number, destinationMap);

      if (path == null || path.Count == 0)
      {
        HasAWPath = false;
        CurAWDest = null;
        return;
      }

      SetNextDestination(path);
      HasAWPath = true;
    }

    private List<int> FindShortestPath(int start, int target)
    {
      var queue = new Queue<List<int>>();
      var visited = new HashSet<int>();

      queue.Enqueue(new List<int> { start });
      visited.Add(start);

      while (queue.Count > 0)
      {
        var path = queue.Dequeue();
        int current = path[path.Count - 1];

        if (!AutoWalkMaps.ContainsKey(current))
          continue;

        var map = AutoWalkMaps[current];

        foreach (var connection in map.ConnectedTo.Keys)
        {
          if (visited.Contains(connection))
            continue;

          var newPath = new List<int>(path) { connection };

          if (connection == target)
            return newPath;

          visited.Add(connection);
          queue.Enqueue(newPath);
        }
      }

      return null;
    }

    private bool TryUseDefaultPath(int map)
    {
      if (AutoWalkMaps.ContainsKey(map) && AutoWalkMaps[map].Default != null)
      {
        CurAWDest = AutoWalkMaps[map].Default;
        HasAWPath = true;
        return true;
      }
      return false;
    }

    private void ResetAutoWalk()
    {
      CurAWDest = null;
      HasAWPath = false;
      Tab.autowalker_button.Text = "Start";
      autowalkon = false;
    }

    private void ResetCheckedFlags()
    {
      foreach (var map in AutoWalkMaps.Values)
        map.Checked = false;
    }

    private void SetNextDestination(List<int> path)
    {
      int currentMap = MapInfo.Number;

      foreach (int next in path)
      {
        if (AutoWalkMaps[currentMap].ConnectedTo.ContainsKey(next))
        {
          var loc = AutoWalkMaps[currentMap].ConnectedTo[next];
          CurAWDest = new Location(loc.X, loc.Y);
          return;
        }
      }
    }

